CREATE TABLE public.ai_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,workspace_id uuid REFERENCES public.workspaces(id) ON DELETE CASCADE,project_id uuid,business_id uuid REFERENCES public.business_store(id) ON DELETE SET NULL,legacy_business_id uuid UNIQUE,title text NOT NULL DEFAULT 'New conversation' CHECK(length(trim(title)) BETWEEN 1 AND 160),busy_request uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,user_id),FOREIGN KEY(project_id,workspace_id) REFERENCES public.projects(id,workspace_id) ON DELETE CASCADE,CHECK(project_id IS NULL OR workspace_id IS NOT NULL));
GRANT SELECT,DELETE ON public.ai_conversations TO authenticated;GRANT INSERT(id,user_id,workspace_id,project_id,business_id,title) ON public.ai_conversations TO authenticated;GRANT UPDATE(title) ON public.ai_conversations TO authenticated;GRANT ALL ON public.ai_conversations TO service_role;
ALTER TABLE public.ai_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_conversations_read ON public.ai_conversations FOR SELECT TO authenticated USING(user_id=auth.uid() AND (workspace_id IS NULL OR public.workspace_role(workspace_id) IS NOT NULL));
CREATE POLICY ai_conversations_create ON public.ai_conversations FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND (workspace_id IS NULL OR public.workspace_role(workspace_id) IS NOT NULL) AND (project_id IS NULL OR EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.workspace_id=workspace_id)) AND (business_id IS NULL OR EXISTS(SELECT 1 FROM public.business_store b WHERE b.id=business_id AND b.user_id=auth.uid())));
CREATE POLICY ai_conversations_rename ON public.ai_conversations FOR UPDATE TO authenticated USING(user_id=auth.uid() AND (workspace_id IS NULL OR public.workspace_role(workspace_id) IS NOT NULL)) WITH CHECK(user_id=auth.uid());
CREATE POLICY ai_conversations_delete ON public.ai_conversations FOR DELETE TO authenticated USING(user_id=auth.uid() AND (workspace_id IS NULL OR public.workspace_role(workspace_id) IS NOT NULL));
CREATE TABLE public.ai_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES public.ai_conversations(id) ON DELETE CASCADE,sdk_id text NOT NULL,role text NOT NULL CHECK(role IN ('user','assistant')),parts jsonb NOT NULL CHECK(jsonb_typeof(parts)='array'),request_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,sdk_id));
GRANT SELECT ON public.ai_messages TO authenticated;GRANT ALL ON public.ai_messages TO service_role;
ALTER TABLE public.ai_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_messages_read ON public.ai_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.ai_conversations c WHERE c.id=conversation_id));
CREATE TABLE public.ai_requests(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES public.ai_conversations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'Processing' CHECK(status IN ('Processing','Completed','Failed','Stopped')),intent text,capabilities jsonb NOT NULL DEFAULT '[]',error_message text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_requests TO authenticated;GRANT ALL ON public.ai_requests TO service_role;
ALTER TABLE public.ai_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_requests_read ON public.ai_requests FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.ai_conversations c WHERE c.id=conversation_id));
CREATE INDEX ai_conversation_user_updated ON public.ai_conversations(user_id,updated_at DESC,id);
CREATE INDEX ai_message_order ON public.ai_messages(conversation_id,created_at,id);
CREATE INDEX ai_request_conversation ON public.ai_requests(conversation_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.guard_ai_conversation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR NEW.project_id IS DISTINCT FROM OLD.project_id THEN RAISE EXCEPTION 'Conversation ownership and workspace/project context are immutable'; END IF;NEW.updated_at=now();END IF;RETURN NEW;END;$$;
CREATE TRIGGER ai_conversation_guard BEFORE UPDATE ON public.ai_conversations FOR EACH ROW EXECUTE FUNCTION public.guard_ai_conversation();
CREATE OR REPLACE FUNCTION public.touch_ai_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now();RETURN NEW;END;$$;
CREATE TRIGGER ai_message_touch BEFORE UPDATE ON public.ai_messages FOR EACH ROW EXECUTE FUNCTION public.touch_ai_record();
CREATE TRIGGER ai_request_touch BEFORE UPDATE ON public.ai_requests FOR EACH ROW EXECUTE FUNCTION public.touch_ai_record();
CREATE OR REPLACE FUNCTION public.begin_ai_request(p_id uuid,p_conversation uuid,p_user uuid) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ BEGIN UPDATE public.ai_conversations SET busy_request=p_id WHERE id=p_conversation AND user_id=p_user AND busy_request IS NULL;IF NOT FOUND THEN RETURN false;END IF;INSERT INTO public.ai_requests(id,conversation_id,user_id) VALUES(p_id,p_conversation,p_user);RETURN true;END;$$;
REVOKE ALL ON FUNCTION public.begin_ai_request(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.begin_ai_request(uuid,uuid,uuid) TO service_role;
INSERT INTO public.ai_conversations(user_id,business_id,legacy_business_id,title,created_at,updated_at) SELECT b.user_id,b.id,b.id,left(b.business_name||' — previous advisor',160),min(m.created_at),max(m.created_at) FROM public.business_store b JOIN public.advisor_messages m ON m.business_id=b.id WHERE b.user_id IS NOT NULL GROUP BY b.id,b.user_id,b.business_name;
INSERT INTO public.ai_messages(conversation_id,sdk_id,role,parts,created_at,updated_at) SELECT c.id,m.id::text,m.role,jsonb_build_array(jsonb_build_object('type','text','text',m.content)),m.created_at,m.created_at FROM public.advisor_messages m JOIN public.ai_conversations c ON c.legacy_business_id=m.business_id WHERE m.role IN ('user','assistant');